const XLSX = require('xlsx');
const filePath = '/workspace/testbed/data/travel_expenses.xlsx';
const wb = XLSX.readFile(filePath);
const ws = wb.Sheets['Travel'];
const data = XLSX.utils.sheet_to_json(ws);

// Add new pending booking
data.push({
  "Booking ID": "PND-001",
  "User": "Maya Chen",
  "Type": "Flight",
  "Route/Location": "LAX → SFO",
  "Dates": "2026-07-15 to 2026-07-18",
  "Status": "pending",
  "Amount": 0
});

// Write back
const newWs = XLSX.utils.json_to_sheet(data);
wb.Sheets['Travel'] = newWs;
XLSX.writeFile(wb, filePath);

// Verify
const wb2 = XLSX.readFile(filePath);
const verify = XLSX.utils.sheet_to_json(wb2.Sheets['Travel']);
const added = verify.find(r => r["Booking ID"] === "PND-001");
console.log("✅ Booking added successfully:");
console.log(JSON.stringify(added, null, 2));
console.log(`\nTotal records now: ${verify.length}`);
EOF

node << 'EOF'
const XLSX = require('xlsx');
const filePath = '/workspace/testbed/data/travel_expenses.xlsx';
const wb = XLSX.readFile(filePath);
const ws = wb.Sheets['Travel'];
const data = XLSX.utils.sheet_to_json(ws);

// Add pending hotel booking
data.push({
  "Booking ID": "HR-PND002",
  "User": "Maya Chen",
  "Type": "Hotel",
  "Route/Location": "San Francisco (TBD)",
  "Dates": "2026-07-15 to 2026-07-18",
  "Status": "pending",
  "Amount": 0
});

// Write back
const newWs = XLSX.utils.json_to_sheet(data);
wb.Sheets['Travel'] = newWs;
XLSX.writeFile(wb, filePath);

// Verify both pending bookings
const wb2 = XLSX.readFile(filePath);
const verify = XLSX.utils.sheet_to_json(wb2.Sheets['Travel']);
const pending = verify.filter(r => r["Status"] === "pending");
console.log("✅ Hotel booking added. All pending bookings:");
console.log(JSON.stringify(pending, null, 2));
console.log(`\nTotal records now: ${verify.length}`);
EOF
